  tool_bmr_tdee_bodyfat_ph: 'e.g. 20',
  tool_bmr_tdee_calculate: 'Calculate',
  tool_bmr_tdee_clear: 'Clear',
  tool_bmr_tdee_description:
    'Estimate basal metabolic rate (BMR) with Mifflin-St Jeor, Harris-Benedict, or Katch-McArdle, then multiply by an activity factor for TDEE. Example: male, 70 kg, 175 cm, age 30, Mifflin, activity 1.55 → BMR ≈ 1648.75 and TDEE ≈ 2555.56 kcal/day. Runs in your browser; educational only — not medical advice.',
  tool_bmr_tdee_disclaimer:
    'BMR and TDEE results are educational estimates only and are not medical, diagnostic, or nutrition advice. Individual needs vary; seek qualified care for health decisions.',
  tool_bmr_tdee_err_generic: 'Check weight, height, age, and (for Katch) body-fat percent.',
  tool_bmr_tdee_example:
    'Example: male, 70 kg, 175 cm, age 30, Mifflin-St Jeor, activity 1.55 → BMR ≈ 1648.75 kcal/day and TDEE ≈ 2555.56 kcal/day.',
  tool_bmr_tdee_example_title: 'Example',
